-- Gremlin World seed data (whitelists). GENERATED by tools/make-gw-seed.py from world-data.json; safe to re-run.
-- It never touches players, sessions, progress, scores or guestbook entries.

on conflict (game_id) do update set machine = excluded.machine, ranked = excluded.ranked, max_score = excluded.max_score, low = excluded.low;

on conflict do nothing;

on conflict do nothing;

on conflict do nothing;

on conflict (id) do update set phrase = excluded.phrase;

on conflict (id) do update set emoji = excluded.emoji, label = excluded.label;
