insert into gw.guestbook_phrases (id, phrase) values
  (1, 'The socks are watching. Kindly.'),
  (2, 'I came for the art, stayed for the stapler.'),
  (3, 'Ten out of ten. Would get lost in the tunnel again.'),
  (4, 'I petted the ficus. It approved.'),
  (5, 'Left a crumb for Grimble. You''re welcome.'),
  (6, 'The chair in the Archive is very good at its job.'),
  (7, 'I found a sock and gave it back. Hero stuff.'),
  (8, 'The kettle and I are friends now.'),
  (9, 'Please tell Moth the paintings are lovely.'),
  (10, 'I lost at Desk Tennis to a stapler. Worth it.'),
  (11, 'Visited the rooftop. The moon waved.'),
  (12, 'My houseplant says hello.'),
  (13, 'Brought snacks. Ate snacks. Sorry.'),
  (14, 'The disco ball is my spirit animal.'),
  (15, 'Please file me under ''snacks''.'),
  (16, 'Noodle, I believe in you.'),
  (17, 'This guestbook smells faintly of tea.'),
  (18, 'Came in quietly. Leaving quietly. Very cozy.'),
  (19, 'Officially a part-time gremlin now.'),
  (20, 'Hello from a very small desk far away.')
